function renderEffectsProperties(o){let area=document.createElement('div');area.innerHTML=`<details open><summary>POSITION VERTICALE</summary>${field('Décalage au-dessus des blocs','objectAltitude','number','min="0" max="32" step="0.1"')}<p class="micro">La carte est indépendante. La hauteur vient des cubes construits et de ce décalage.</p></details><details><summary>EFFET ANIMÉ</summary><label>Effet<select id="objectEffect"><option value="">Aucun</option>${Object.entries(W.FX).map(([k,v])=>`<option value="${k}">${v.name}</option>`).join('')}</select></label>${field('Couleur','effectColor','color')}${field('Rayon / taille','effectSize','number','min="0.2" max="12" step="0.2"')}${field('Vitesse','effectSpeed','number','min="0.1" max="3" step="0.1"')}${field('Densité','effectDensity','number','min="0.2" max="3" step="0.2"')}</details><details><summary>AURA</summary>${check('Activer l’aura','auraEnabled')}<label>Style<select id="auraKind">${Object.entries(W.AURAS).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label>${field('Couleur de l’aura','auraColor','color')}${field('Rayon de l’aura','auraRadius','number','min="0.2" max="12" step="0.2"')}${field('Hauteur de l’énergie × personnage','auraHeight','number','min="0.5" max="4" step="0.1"')}${field('Vitesse de l’énergie','auraSpeed','number','min="0.2" max="3" step="0.1"')}${check('Éclairs autour de l’énergie','auraLightning')}<p class="micro">Énergie : enveloppe verticale et particules ascendantes. La couleur reste personnalisable. Anneaux et runes sont des effets au sol.</p>${field('Intensité','auraIntensity','number','min="0.1" max="1" step="0.1"')}</details>`;$('#inspector').append(area);o.level??=0;o.offsetZ??=0;o.aura??={enabled:false,kind:'energy',color:'#ffe071',radius:.8,intensity:.7,height:1.55,speed:1,lightning:true};o.effect??={kind:'',color:'#ffac43',size:1,speed:1,density:1};numeric('objectAltitude',o,'offsetZ',0,32);$('#objectEffect').value=o.effect.kind;$('#objectEffect').onchange=e=>change(()=>{o.effect.kind=e.target.value;if(W.FX[e.target.value])o.effect.color=W.FX[e.target.value].color});$('#effectColor').value=o.effect.color;$('#effectColor').onchange=e=>change(()=>{o.effect.color=e.target.value});numeric('effectSize',o.effect,'size',.2,12);numeric('effectSpeed',o.effect,'speed',.1,3);numeric('effectDensity',o.effect,'density',.2,3);bool('auraEnabled',o.aura,'enabled');$('#auraKind').value=o.aura.kind;$('#auraKind').onchange=e=>change(()=>{o.aura.kind=e.target.value;const preset={energy:'#ffe071',azure:'#65dfff',crimson:'#ff526c'}[o.aura.kind];if(preset)o.aura.color=preset});$('#auraColor').value=o.aura.color;$('#auraColor').onchange=e=>change(()=>{o.aura.color=e.target.value});numeric('auraRadius',o.aura,'radius',.2,12);numeric('auraIntensity',o.aura,'intensity',.1,1);o.aura.height??=1.55;o.aura.speed??=1;o.aura.lightning??=true;numeric('auraHeight',o.aura,'height',.5,4);numeric('auraSpeed',o.aura,'speed',.2,3);bool('auraLightning',o.aura,'lightning');}
function renderExtraProperties(o){if(o.type==='tree'){let area=document.createElement('div');area.innerHTML='<h3>Arbre et feuillage</h3><label>Variété<select id="treeVariant"><option value="oak">Chêne</option><option value="pine">Sapin</option><option value="birch">Bouleau</option><option value="willow">Saule</option></select></label>'+field('Largeur du feuillage','treeCanopy','number','min="0.5" max="3" step="0.1"')+field('Rayon du tronc (collision)','treeTrunk','number','min="0.05" max="0.4" step="0.01"')+'<p class="micro">Le feuillage ne bloque pas la vue. Seul le tronc intervient dans les collisions et, si activé, dans la visibilité.</p>';$('#inspector').append(area);$('#treeVariant').value=o.variant||'oak';$('#treeVariant').onchange=e=>change(()=>{o.variant=e.target.value});numeric('treeCanopy',o,'canopy',.5,3);numeric('treeTrunk',o,'trunkRadius',.05,.4)}if(W.isSegment(o)){let b=document.createElement('button');b.className='wide primary';b.textContent=W.isDoor(o)?(o.open?'Fermer la porte':'Ouvrir la porte'):'Transformer ce segment en porte';b.onclick=()=>W.isDoor(o)?toggleDoor(o):convertToDoor(o);$('#inspector').append(b)}}
function convertToDoor(o){if(locked(o)){toast('Déverrouillez le segment avant de le transformer.');return}change(()=>{o.type='door';o.name='Porte';o.color='#a58b61';o.open=false;o.blocking=true;o.blocksSight=true})}
function toggleDoor(o){let a=actor();if(viewMode!=='mj'&&(!a||Math.hypot(W.center(a).x-W.center(o).x,W.center(a).y-W.center(o).y)>2)){toast('Approchez-vous de la porte pour l’actionner.');return}if(o.open&&!W.canCloseDoor(map(),o)){toast('Un personnage est dans le passage : impossible de fermer.');return}change(()=>{o.open=!o.open});toast(o.open?'Porte ouverte : passage et vue dégagés.':'Porte fermée : passage et vue bloqués.')}
function nearestDoor(){let a=actor();if(!a)return;let p=W.center(a);return map().objects.filter(o=>W.isDoor(o)&&W.levelOf(o)===W.levelOf(a)).map(o=>({o,d:Math.hypot(W.center(o).x-p.x,W.center(o).y-p.y)})).filter(t=>t.d<=2).sort((a,b)=>a.d-b.d)[0]?.o}
function renderResourceBars(o,form){let section=document.createElement('details');section.open=true;let title=document.createElement('summary');title.textContent='BARRES PERSONNALISÉES';section.append(title);let list=document.createElement('div');list.id='resourceBars';section.append(list);for(let b of o.bars||[]){let row=document.createElement('div');row.className='resource-editor';for(let [key,label,type]of [['name','Nom','text'],['value','Valeur','number'],['max','Maximum','number'],['color','Couleur','color']]){let wrap=document.createElement('label');wrap.textContent=label;let input=document.createElement('input');input.type=type;input.value=b[key];input.setAttribute('aria-label',label+' de la barre');if(key==='max')input.min='1';input.onchange=e=>{let value=type==='number'?Number(e.target.value):e.target.value;if(type==='number'&&!Number.isFinite(value))return;change(()=>{b[key]=key==='max'?Math.max(1,value):value})};wrap.append(input);row.append(wrap)}let visible=document.createElement('label');visible.className='check';let toggle=document.createElement('input');toggle.type='checkbox';toggle.checked=b.visible!==false;toggle.onchange=e=>change(()=>{b.visible=e.target.checked});visible.append(toggle);let caption=document.createElement('span');caption.textContent='Visible';visible.append(caption);let remove=document.createElement('button');remove.textContent='Supprimer';remove.onclick=()=>change(()=>{o.bars=o.bars.filter(r=>r!==b)});row.append(visible,remove);list.append(row)}let add=document.createElement('button');add.id='addResourceBar';add.textContent='Ajouter une barre';add.onclick=()=>change(()=>{o.bars??=[];o.bars.push({id:uid(),name:'Ressource '+(o.bars.length+1),value:10,max:10,color:'#78b7db',visible:true})});section.append(add);form.append(section)}
function focusObject(o){if(map().camera.mode==='fly'){recenterPlayer(o);schedule();return}if(map().camera.mode==='third'){map().camera.followId=o.id;schedule();return}if(map().camera.mode==='fly'){let p=W.center(o);map().camera.fly={x:p.x+4,y:W.elevation(o,map())+5,z:p.y+4};schedule();return}let p=W.center(o),screen=scene.screen(p.x,p.y,W.elevation(o,map()));map().camera.panX+=canvas.clientWidth/2-screen.x;map().camera.panY+=canvas.clientHeight/2-screen.y;schedule()}
function deleteObject(o){if(locked(o)){toast('Déverrouillez l’élément ou son groupe avant de le supprimer.');return}change(()=>{map().objects=map().objects.filter(a=>a.id!==o.id);selection=null});toast('Élément supprimé · Ctrl+Z pour restaurer.')}
