const dbReady=new Promise((resolve,reject)=>{let r=indexedDB.open('brumes-images',1);r.onupgradeneeded=()=>r.result.createObjectStore('images');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});dbReady.catch(()=>toast('Stockage des images indisponible.'));
async function storeImage(id,data){let db=await dbReady;await new Promise((resolve,reject)=>{let tx=db.transaction('images','readwrite');tx.objectStore('images').put(data,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
async function loadImage(id){if(!id||images.has(id))return images.get(id);if(imageLoading.has(id))return imageLoading.get(id);let promise=(async()=>{try{let data=npcImageURL(id);if(!data){let db=await dbReady;data=await new Promise((resolve,reject)=>{let r=db.transaction('images').objectStore('images').get(id);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}if(!data)return;let im=await decodeImage(data),buffer=document.createElement('canvas');buffer.width=im.width;buffer.height=im.height;let c=buffer.getContext('2d');c.drawImage(im,0,0);im.pixels=c.getImageData(0,0,im.width,im.height).data;images.set(id,im);schedule();updateImagePreview();return im}catch{toast('Une image ne peut pas être chargée.')}})();imageLoading.set(id,promise);try{return await promise}finally{imageLoading.delete(id)}}
