function renderImageProperties(o){let root=$('#imageProperties');root.innerHTML=`${W.character(o)?'<section class="npc-presets"><h3>Apparences intégrées · 16 directions</h3><div id="npcPresetGrid" class="npc-preset-grid"></div><div class="row"><button id="npcPresetRandom" type="button">Apparence aléatoire</button><button id="npcPresetClear" type="button">Sans preset</button></div><p class="micro">Choisissez une apparence pour ce personnage. Les images personnelles sont conservées tant que vous ne choisissez pas un autre preset ; Annuler restaure le choix précédent.</p></section>':''}<details open><summary>${W.isSegment(o)?'TEXTURE DU MUR / DE LA PORTE':'IMAGES ET VUES DIRECTIONNELLES'}</summary>${W.isSegment(o)?'<p class="micro">L’image est appliquée sur les faces du volume. La géométrie et les collisions sont conservées.</p>'+field('Taille du motif (cases)','textureScale','number','min="0.2" max="12" step="0.1"'):''}${W.character(o)?check('Jeton debout fixe · ne suit pas la caméra','tokenFixed')+check('Jeton posé à plat au sol','imageFlat'):''}${field('Décalage des vues (°)','frameOffset','number','min="-360" max="360" step="1"')}<label>Source des apparences<select id="appearanceSource"><option value="files">Plusieurs images · une par direction</option><option value="single">Une image · cadrage et zoom</option><option value="sheet">Planche de sprites · grille</option></select></label><div id="individualSettings">${check('Adapter les directions au lot importé','autoImageCount')}<label>Nombre de directions<input id="frameCount" type="number" min="1" max="4096" value="${o.frameCount||1}"></label><p class="micro">2 images = 2 directions. 256 images = 256 directions. De 1 à 4096, sans obligation de puissance de deux.</p></div><div id="spriteSettings"><label class="upload">Charger l’image source<input id="uploadSheet" type="file" accept="image/png,image/webp,image/jpeg"></label><div class="row">${field('Colonnes','sheetCols','number','min="1" max="256"')}${field('Lignes','sheetRows','number','min="1" max="256"')}</div><div class="row">${field('Directions à extraire','sheetCount','number','min="1" max="4096"')}${field('Première case (1…)','sheetStart','number','min="1"')}</div>${field('Zoom du cadrage','sheetZoom','number','min="1" max="8" step="0.1"')}<div class="row">${field('Centre horizontal (%)','sheetX','number','min="0" max="100"')}${field('Centre vertical (%)','sheetY','number','min="0" max="100"')}</div><div id="sheetPreview" class="sheet-preview"></div><p class="micro">Lecture de gauche à droite, puis de haut en bas. Le cadrage reste à l’intérieur de chaque case.</p><button id="applySheet" class="wide primary">Appliquer le cadrage</button><p id="sheetStatus" class="micro"></p></div><p class="micro">Tournez l’aperçu, puis ajoutez l’image de cet angle. Les angles sans image utilisent l’image de secours.</p><section class="portrait-studio"><header><span id="currentFrame"></span><span id="portraitDegrees">0°</span></header><div id="imagePreview" class="portrait-stage" tabindex="0" role="group" aria-label="Aperçu 3D rotatif : glisser ou utiliser les flèches gauche et droite"></div><p class="portrait-hint">Glissez pour tourner · déposez une image pour cet angle</p><div class="portrait-orbit"><input id="portraitAngle" aria-label="Rotation de l’aperçu" type="range" min="0" max="359.999" step="0.01"><button id="portraitFront" type="button">Face</button></div><p id="portraitStatus" class="micro"></p><label class="upload portrait-upload"><span id="portraitUploadLabel">Choisir l’image</span><input id="uploadImages" type="file" accept="image/png,image/webp,image/jpeg" multiple></label></section><details class="portrait-advanced"><summary>Réglages des images</summary><label>Source à modifier<select id="imageSlot"><option value="base">Image de secours</option><option value="direction">Angle de l’aperçu</option></select></label><div class="row"><button id="previousFrame">Précédente</button><label>Vue<input id="frameNumber" type="number" min="1" max="${o.frameCount||1}" value="1"></label><button id="nextFrame">Suivante</button></div><p class="micro">Import multiple : tri par nom, à partir de l’angle choisi. PNG, WebP ou JPG, 10 Mo par image.</p><div class="row"><button id="clearImage">Retirer cette image</button><button id="flipImage">Miroir</button></div></details>${field('Échelle de l’image','imageScale','number','min="0.2" max="5" step="0.1"')}${field('Opacité','imageOpacity','number','min="0.1" max="1" step="0.05"')}${!W.character(o)&&!W.isSegment(o)?check('Image posée à plat au sol','imageFlat'):''}</details>`;
 if($('#labelMode')){$('#labelMode').value=o.labelMode||'compact';$('#labelMode').onchange=e=>change(()=>{o.labelMode=e.target.value})}if($('#tokenFixed'))bool('tokenFixed',o,'tokenFixed');if($('#frameOffset'))numeric('frameOffset',o,'frameOffset',-360,360);if(W.isSegment(o)){o.textureScale??=1;numeric('textureScale',o,'textureScale',.2,12)}$('#frameCount').onchange=e=>{let count=Number(e.target.value);if(!W.validFrameCount(count)){toast('Choisissez entre 1 et 4096 directions.');renderInspector();return}change(()=>{o.frameSets??={};o.frameSets[o.frameCount||1]={...o.frames};let next=o.frameSets[count];if(!next){next={};for(let[k,v]of Object.entries(o.frames||{})){let index=W.mod(Math.round(Number(k)*count/(o.frameCount||1)),count);if(!next[index])next[index]=v}}o.frames={...next};o.frameCount=count;imageEdit.frame=angleFrame(portraitAngle,count)+1;imageEdit.slot=count===1?'base':'direction'})};$('#imageSlot').onchange=updateImagePreview;$('#frameNumber').onchange=()=>{$('#frameNumber').value=W.clamp(Math.floor(Number($('#frameNumber').value)||1),1,o.frameCount||1);portraitAngle=(Number($('#frameNumber').value)-1)*360/(o.frameCount||1);updateImagePreview()};$('#previousFrame').onclick=()=>{$('#frameNumber').value=W.mod(Number($('#frameNumber').value)-2,o.frameCount||1)+1;$('#imageSlot').value='direction';portraitAngle=(Number($('#frameNumber').value)-1)*360/(o.frameCount||1);updateImagePreview()};$('#nextFrame').onclick=()=>{$('#frameNumber').value=W.mod(Number($('#frameNumber').value),o.frameCount||1)+1;$('#imageSlot').value='direction';portraitAngle=(Number($('#frameNumber').value)-1)*360/(o.frameCount||1);updateImagePreview()};$('#clearImage').onclick=()=>{let slot=$('#imageSlot').value,index=Number($('#frameNumber').value)-1;change(()=>{if(slot==='base')delete o.imageId;else if(o.frames)delete o.frames[index]})};$('#flipImage').onclick=()=>change(()=>{o.flip=!o.flip});numeric('imageScale',o,'scale',.2,5);numeric('imageOpacity',o,'opacity',.1,1);if($('#imageFlat'))bool('imageFlat',o,'flat');$('#uploadImages').onchange=e=>importFiles([...e.target.files],o,$('#imageSlot').value,Number($('#frameNumber').value)-1);if(imageEdit.id===o.id){$('#imageSlot').value=imageEdit.slot;$('#frameNumber').value=Math.min(imageEdit.frame,o.frameCount||1)}else{portraitAngle=0;$('#imageSlot').value=(o.frameCount||1)>1?'direction':'base'}bindPortrait();bindSpriteSettings(o);bindNpcPresets(o);updateImagePreview();}
function bindNpcPresets(o){const grid=$('#npcPresetGrid');if(!grid)return;const current=currentNpcPreset(o);function choose(id){change(()=>{applyNpcPreset(o,id);portraitAngle=0;imageEdit={id:o.id,slot:'direction',frame:1}});loadNpcAppearance(o)}for(const p of NPC_PRESETS){const b=document.createElement('button');b.type='button';b.className='npc-preset'+(current===p.id?' chosen':'');b.setAttribute('aria-pressed',String(current===p.id));const im=document.createElement('img');im.src=npcImageURL(npcFrameId(p.id,0));im.alt='';im.loading='lazy';const name=document.createElement('span');name.textContent=p.name;b.append(im,name);b.onclick=()=>choose(p.id);grid.append(b)}$('#npcPresetRandom').onclick=()=>{const choices=NPC_PRESETS.filter(p=>p.id!==current);choose(choices[Math.floor(Math.random()*choices.length)].id)};$('#npcPresetClear').onclick=()=>change(()=>{clearNpcPreset(o);portraitAngle=0;imageEdit={id:o.id,slot:'base',frame:1}})}
async function importFiles(files,o,slot,start){if(!files.length)return;if(files.length>4096){toast('Maximum 4096 images par lot.');return}let autoFit=o.autoImageCount!==false&&files.length>1&&!W.isSegment(o)&&!o.surface;if(autoFit)start=0;files.sort((a,b)=>a.name.localeCompare(b.name,undefined,{numeric:true}));if(files.some(f=>!['image/png','image/webp','image/jpeg'].includes(f.type)||f.size>10*1024*1024)){toast('PNG, WebP ou JPG, maximum 10 Mo par image.');return}if(W.isSegment(o)||o.surface){files=files.slice(0,1);slot='base'}else if(files.length>1)slot='direction';if(!autoFit&&slot==='direction'&&start+files.length>(o.frameCount||1)){toast('Augmentez le nombre de vues ou réduisez le nombre de fichiers.');return}toast('Import et préparation des images…');let prepared=[];try{for(let file of files){let url=URL.createObjectURL(file);try{let im=await decodeImage(url);if(im.width*im.height>40000000)throw Error('Image trop grande');let ratio=Math.min(1,Math.min(768,Math.floor(Math.sqrt(16000000/files.length)))/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.width*ratio));c.height=Math.max(1,Math.round(im.height*ratio));let g=c.getContext('2d');g.drawImage(im,0,0,c.width,c.height);let data=g.getImageData(0,0,c.width,c.height).data,minX=c.width,minY=c.height,maxX=-1,maxY=-1;for(let y=0;y<c.height;y++)for(let x=0;x<c.width;x++)if(data[(y*c.width+x)*4+3]){minX=Math.min(minX,x);maxX=Math.max(maxX,x);minY=Math.min(minY,y);maxY=Math.max(maxY,y)}if(maxX<0)throw Error('Image entièrement transparente');let crop=document.createElement('canvas');crop.width=maxX-minX+1;crop.height=maxY-minY+1;crop.getContext('2d').drawImage(c,minX,minY,crop.width,crop.height,0,0,crop.width,crop.height);let id=uid();await storeImage(id,crop.toDataURL('image/png'));prepared.push(id);await loadImage(id)}finally{URL.revokeObjectURL(url)}}let live=world.maps.flatMap(m=>m.objects).find(t=>t.id===o.id);if(!live)return;change(()=>{if(autoFit){live.frameSets??={};live.frameSets[live.frameCount||1]={...live.frames};live.frameCount=prepared.length;live.frames={};imageEdit.frame=1;imageEdit.slot='direction';portraitAngle=0}if(slot==='base')live.imageId=prepared[0];else{live.frames??={};prepared.forEach((id,i)=>live.frames[start+i]=id);if(!live.imageId)live.imageId=prepared[0]}});toast(`${prepared.length} image(s) importée(s), transparence conservée.`)}catch(e){toast('Import annulé : '+(e.message||'image ou stockage indisponible'))}}
function sheetDraft(o){let single=o.appearanceSource==='single';return{cols:single?1:Number($('#sheetCols').value),rows:single?1:Number($('#sheetRows').value),count:single?1:Number($('#sheetCount').value),start:single?0:Number($('#sheetStart').value)-1,zoom:Number($('#sheetZoom').value),x:Number($('#sheetX').value),y:Number($('#sheetY').value)}}
function drawSheetPreview(o){let el=$('#sheetPreview');if(!el||!o.sheetId)return;let im=images.get(o.sheetId);if(!im)return;try{let d=sheetDraft(o),rects=spriteRects(im.width,im.height,d),r=rects[angleFrame(portraitAngle,d.count)];el.replaceChildren();let pic=document.createElement('img');pic.src=im.src;pic.alt='Image source et cadre de la direction sélectionnée';let box=document.createElement('span');box.style.cssText=`left:${r.x/im.width*100}%;top:${r.y/im.height*100}%;width:${r.w/im.width*100}%;height:${r.h/im.height*100}%`;el.append(pic,box);$('#sheetStatus').textContent=`${d.count} direction(s) · case ${d.start+angleFrame(portraitAngle,d.count)+1} · ${Math.round(r.w)} × ${Math.round(r.h)} px`;}catch(e){$('#sheetStatus').textContent=e.message}}
function bindSpriteSettings(o){let mode=o.appearanceSource||'files';$('#appearanceSource').value=mode;$('#appearanceSource').onchange=e=>change(()=>{o.appearanceSource=e.target.value});$('#individualSettings').hidden=mode!=='files';$('#spriteSettings').hidden=mode==='files';{let label=$('#uploadImages').closest('label');if(label)label.hidden=mode!=='files'};o.autoImageCount??=true;bool('autoImageCount',o,'autoImageCount');let conf=o.spriteConfigs?.[mode]||{cols:4,rows:2,count:8,start:0,zoom:1,x:50,y:50};for(let[id,key]of [['sheetCols','cols'],['sheetRows','rows'],['sheetCount','count'],['sheetStart','start'],['sheetZoom','zoom'],['sheetX','x'],['sheetY','y']]){let input=$('#'+id);input.value=key==='start'?conf[key]+1:conf[key];{let label=input.closest('label');if(label)label.hidden=mode==='single'&&['cols','rows','count','start'].includes(key)};input.oninput=()=>drawSheetPreview(o);input.onchange=()=>{try{let d=sheetDraft(o),im=images.get(o.sheetId);spriteRects(im?.width||4096,im?.height||4096,d);change(()=>{o.spriteConfigs??={};o.spriteConfigs[mode]=d})}catch(e){toast(e.message);renderInspector()}}}$('#uploadSheet').onchange=e=>importSheet(e.target.files[0],o);$('#applySheet').onclick=()=>applySpriteSheet(o);$('#applySheet').disabled=!o.sheetId;drawSheetPreview(o)}
async function importSheet(file,o){if(!file)return;if(!['image/png','image/webp','image/jpeg'].includes(file.type)||file.size>10*1024*1024){toast('PNG, WebP ou JPG, maximum 10 Mo.');return}let url=URL.createObjectURL(file);try{let im=await decodeImage(url);if(im.width*im.height>40000000)throw Error('Image trop grande (40 mégapixels maximum).');let c=document.createElement('canvas'),ratio=Math.min(1,4096/Math.max(im.width,im.height));c.width=Math.round(im.width*ratio);c.height=Math.round(im.height*ratio);c.getContext('2d').drawImage(im,0,0,c.width,c.height);let id=uid();await storeImage(id,c.toDataURL('image/png'));await loadImage(id);if(!world.maps.some(m=>m.objects.includes(o)))return;change(()=>{o.sheetId=id});toast('Source chargée. Réglez le cadre puis appliquez.')}catch(e){toast('Import impossible : '+e.message)}finally{URL.revokeObjectURL(url)}}
let sheetApplying=false;
