function renderMaps(){let m=map();$('#mapList').replaceChildren();for(let a of world.maps){let b=document.createElement('button');b.className='mapcard'+(a.id===m.id?' current':'');let wrap=document.createElement('div'),name=document.createElement('span'),meta=document.createElement('small');name.textContent=a.name;meta.textContent=`${a.width} × ${a.height} · ${a.objects.length} éléments`;wrap.append(name,meta);b.append(wrap);b.onclick=()=>{switchMap(a.id);renderMaps()};$('#mapList').append(b)}$('#editMapName').value=m.name;$('#mapWidth').value=m.width;$('#mapHeight').value=m.height;$('#connectionList').replaceChildren();for(let p of m.objects.filter(o=>o.type==='portal')){let e=document.createElement('div');e.className='connection';e.textContent=`${p.name} → ${world.maps.find(t=>t.id===p.target)?.name||'destination à définir'}`;$('#connectionList').append(e)}if(!m.objects.some(o=>o.type==='portal'))$('#connectionList').textContent='Aucun passage.';let grid=$('#chunkGrid'),cols=Math.min(16,Math.ceil(m.width/16)+1),rows=Math.min(16,Math.ceil(m.height/16)+1);grid.replaceChildren();grid.style.gridTemplateColumns=`repeat(${cols}, minmax(30px, 1fr))`;for(let cy=0;cy<rows;cy++)for(let cx=0;cx<cols;cx++){let b=document.createElement('button'),key=`${cx},${cy}`;b.textContent=`${cx+1} · ${cy+1}`;b.classList.toggle('loaded',m.chunks.includes(key));b.title=`Activer le chunk ${cx+1}, ${cy+1}`;b.onclick=()=>{if(m.chunks.includes(key)&&m.width>=(cx+1)*16&&m.height>=(cy+1)*16)return;change(()=>W.addChunk(m,cx,cy));renderMaps()};grid.append(b)}}
function resizeMap(){let m=map(),w=Number($('#mapWidth').value),h=Number($('#mapHeight').value);if(!Number.isInteger(w)||!Number.isInteger(h)||w<8||h<8||w>W.MAX_MAP||h>W.MAX_MAP){toast('Dimensions entières entre 8 et 4096 cases.');return}let candidate={...m,width:w,height:h,chunks:W.allChunks(w,h)};if(m.objects.some(o=>!W.validObject(candidate,o))||world.maps.some(other=>other.objects.some(p=>p.type==='portal'&&p.target===m.id&&!W.activeCell(candidate,p.spawnX??1,p.spawnY??1)))){toast('Des éléments dépasseraient les nouvelles dimensions. Déplacez-les d’abord.');return}change(()=>{m.width=w;m.height=h;m.chunks=W.allChunks(w,h);m.fog=m.fog.filter(k=>{let[x,y]=k.split(',').map(Number);return x<w&&y<h});m.terrain=Object.fromEntries(Object.entries(m.terrain||{}).filter(([k])=>{let[x,y]=k.split(',').map(Number);return x<w&&y<h}));m.effects=(m.effects||[]).filter(e=>e.x<w&&e.y<h);if(m.blocks)m.blocks=Object.fromEntries(Object.entries(m.blocks).filter(([k])=>{let[x,y]=k.split(',').map(Number);return x<w&&y<h}));for(let field of ['ground','blockHeights'])if(m[field])m[field]=Object.fromEntries(Object.entries(m[field]).filter(([k])=>{let[x,y]=k.split(',').map(Number);return x<w&&y<h}));m.blockRevision=(m.blockRevision||0)+1;m.extensions=[];m.camera.panX=0;m.camera.panY=0;m.camera.zoom=1});renderMaps()}
