function stopMovement(){cancelPath();clearTimeout(previewTimer);routeFor=null;if(moving){moving.actor.x=moving.last.x;moving.actor.y=moving.last.y;if(moving.last.z!==undefined)moving.actor.voxelZ=moving.last.z;if(moving.kind==='stairs'){moving.actor.level=moving.last.level;delete moving.actor.travelZ;delete map().transitionLevel}moving=null;invalidate();save()}route=[];$('#pathBadge').hidden=true;}
