 map().groups.push({id:gid,name:'Pièce '+(map().groups.length-2),color:$('#brushColor').value,visible:true,locked:false});
 map().objects.push(...walls);selection=walls.at(-1).id;
 for(let xx=x;xx<x+w;xx++)for(let yy=y;yy<y+h;yy++)map().floor[W.cellKey(xx,yy)]=$('#brushColor').value;
