function flyTick(time){flyFrame=0;if(document.hidden||editingTarget(document.activeElement)||$('dialog[open]')){clearNavigationInput();return}if(!['fly','third'].includes(map().camera.mode)||!flyKeys.size){flyTime=0;return}let dt=flyTime?Math.min(.05,(time-flyTime)/1000):.016;flyTime=time;let c=map().camera,p=c.mode==='third'?(c.scout??={x:0,y:0,z:0}):c.fly;if(!p)return;const previous=c.mode==='fly'?{...p}:null;let a=c.angle,fx=-(Math.cos(a)+Math.sin(a))/Math.SQRT2,fz=-(Math.cos(a)-Math.sin(a))/Math.SQRT2,forward=(flyKeys.has('forward')?1:0)-(flyKeys.has('back')?1:0),side=(flyKeys.has('right')?1:0)-(flyKeys.has('left')?1:0),up=(flyKeys.has('up')?1:0)-(flyKeys.has('down')?1:0),speed=dt*(flyKeys.has('boost')?24:8)/Math.max(1,Math.hypot(forward,side,up));p.x+=speed*(fx*forward-fz*side);p.z+=speed*(fz*forward+fx*side);p.y=W.clamp(p.y+speed*up,-20,100);limitPlayerCamera(previous);if(creativeActive())creativeAimDirty=true;queueSave();schedule();flyFrame=requestAnimationFrame(flyTick)}
