 if(creativeZoneA&&creativeZoneB){creativeZone=BT.zoneBounds(creativeZoneA,creativeZoneB);creativeZone.h=Math.max(1,Math.ceil(creativeZone.h));creativeZone.z=Math.floor(creativeZone.z);$('#creativeZoneZ').value=creativeZone.z;$('#creativeZoneH').value=creativeZone.h;drawBrush={...creativeZone,zone:true};$('#creativeZoneInfo').textContent=`${creativeZone.w} × ${creativeZone.d} · base ${creativeZone.z} · hauteur ${creativeZone.h}`}
 else $('#creativeZoneInfo').textContent=(creativeZoneA?'Coin A':'Coin B')+' défini. Cliquez l’autre coin.';
