 if(e.button!==0&&e.button!==2)return true;e.preventDefault?.();canvas.focus({preventScroll:true});creativeLastEvent={clientX:e.clientX,clientY:e.clientY};
 if(item?.kind==='inspect'){selectObject(creativePick(e));if(document.pointerLockElement===canvas)document.exitPointerLock?.();showPanel('inspectorPanel');return true}if(item?.kind==='pipette'){sampleCreative();return true}if(item?.kind==='frame'){if(e.button===2){placeCreativeFrame(creativePoint(e));if(document.pointerLockElement===canvas)document.exitPointerLock?.();showPanel('inspectorPanel')}return true}
