function renderActorFootprint(o){if(!W.character(o))return;let area=document.createElement('div');area.innerHTML=`<details open><summary>TAILLE ET OCCUPATION AU SOL</summary><div class="row">${field('Largeur en cases','actorWidth','number','min="1" max="12" step="1"')}${field('Profondeur en cases','actorDepth','number','min="1" max="12" step="1"')}</div><div class="row">${field('Hauteur du monstre','actorBodyHeight','number','min="0.5" max="32" step="0.1"')}${field('Passage sous le corps','actorClearance','number','min="0" max="30" step="0.1"')}</div><p class="micro">Cliquez une case : pleine → passage dessous → vide. La grille reste alignée sur la carte, indépendamment du regard.</p><div id="actorFootprint" class="actor-footprint" role="group" aria-label="Grille d’occupation du personnage"></div><div class="row"><button id="footprintSolid">Tout occuper</button><button id="footprintUnder">Passage dessous</button></div><p class="micro">Plein : bloque depuis le sol. Passage : bloque seulement au-dessus de la hauteur libre. Vide : aucune collision. Dimensions de 1 à 12 cases.</p></details>`;$('#inspector').append(area);let w=Math.round(o.w||1),d=Math.round(o.d||1);$('#actorWidth').value=w;$('#actorDepth').value=d;$('#actorBodyHeight').value=o.bodyHeight||o.height||1.8;$('#actorClearance').value=o.underClearance??2.5;const apply=updates=>{let next={...o,...updates};if(!W.validObject(map(),next)||!W.cellFree(map(),next.x,next.y,next)){toast('Cette occupation rencontre un obstacle ou dépasse la carte.');renderInspector();return}change(()=>Object.assign(o,updates))};for(let[id,key]of [['actorWidth','w'],['actorDepth','d']])$('#'+id).onchange=e=>{let n=Number(e.target.value);if(!Number.isInteger(n)||n<1||n>12){toast('Choisissez de 1 à 12 cases.');renderInspector();return}let nw=key==='w'?n:w,nd=key==='d'?n:d,cells=Array.from({length:nw*nd},(_,i)=>{let x=i%nw,y=Math.floor(i/nw);return x<w&&y<d?(o.occupancy?.[y*w+x]??1):1});apply({w:nw,d:nd,occupancy:cells})};$('#actorBodyHeight').onchange=e=>{let n=Number(e.target.value);if(!Number.isFinite(n)||n<.5||n>32){renderInspector();return}apply({height:n,bodyHeight:n})};$('#actorClearance').onchange=e=>{let n=Number(e.target.value);if(!Number.isFinite(n)||n<0||n>30){renderInspector();return}apply({underClearance:n})};let grid=$('#actorFootprint');grid.style.setProperty('--footprint-cols',w);for(let y=0;y<d;y++)for(let x=0;x<w;x++){let i=y*w+x,kind=o.occupancy?.[i]??1,b=document.createElement('button');b.type='button';b.className='footprint-cell kind-'+kind;b.textContent=['·','■','⌒'][kind];b.setAttribute('aria-label',`Case ${x+1}, ${y+1} : ${['vide','pleine','passage dessous'][kind]}`);b.onclick=()=>{let cells=o.occupancy?[...o.occupancy]:Array(w*d).fill(1);cells[i]=(kind+1)%3;apply({occupancy:cells})};grid.append(b)}$('#footprintSolid').onclick=()=>apply({occupancy:Array(w*d).fill(1)});$('#footprintUnder').onclick=()=>apply({occupancy:Array(w*d).fill(2)});}

function creativeConfig(){const item=heldItem();if(['brush','fogbrush'].includes(item?.kind))return item;world.builder.zoneTool??=CT.defaultToolConfig();return world.builder.zoneTool}
function syncCreativeSettings(){if(!$('#editMaterial'))return;$('#creativeReach').value=world.builder?.reach||12;const conf=creativeConfig();for(const[id,key]of [['editSize','size'],['editHeight','height'],['editMaterial','material'],['editShape','shape'],['editMask','mask'],['editSeed','seed']])$('#'+id).value=conf[key]??CT.defaultToolConfig()[key];$('#editPatternEnabled').checked=!!conf.patternEnabled;$('#volumeSettings').hidden=!['brush','selection'].includes(heldItem()?.kind);renderCreativePattern();}
function renderCreativePattern(){const conf=creativeConfig();conf.pattern??=CT.defaultToolConfig().pattern;const root=$('#editPatternRows');if(!root)return;root.replaceChildren();root.hidden=!conf.patternEnabled;for(const [index,row]of conf.pattern.entries()){let wrap=document.createElement('div');wrap.className='edit-pattern-row';let select=document.createElement('select');select.setAttribute('aria-label','Matériau du motif '+(index+1));for(let[id,label]of [['air','Air (retirer)'],...Object.entries(W.BLOCKS).map(([id,b])=>[id,b.name])]){let op=document.createElement('option');op.value=id;op.textContent=label;select.append(op)}select.value=row.material;select.onchange=e=>{row.material=e.target.value;queueSave()};let weight=document.createElement('input');weight.type='number';weight.min=0;weight.max=100;weight.step=1;weight.value=row.weight;weight.setAttribute('aria-label','Pourcentage '+(index+1));weight.onchange=e=>{row.weight=Number(e.target.value);queueSave();renderCreativePattern()};let remove=document.createElement('button');remove.textContent='×';remove.setAttribute('aria-label','Retirer le matériau '+(index+1));remove.onclick=()=>{conf.pattern.splice(index,1);queueSave();renderCreativePattern()};wrap.append(select,weight,remove);root.append(wrap)}const sum=conf.pattern.reduce((s,r)=>s+Number(r.weight||0),0);$('#editPatternTotal').textContent=conf.patternEnabled?'Total : '+sum+' %'+(sum===100?'':' · attendu : 100 %'):'';}
function sampleCreative(){const p=creativePoint(),id=creativePick(),o=map().objects.find(o=>o.id===id),material=o?o.material:p.block?W.blockAt(map(),p.block.x,p.block.y,p.block.z):(p.ground?'grass':null);if(material){assignSlot({kind:'block',material,w:o?.w||1,d:o?.d||1,h:o?.height||(p.block?W.blockSize(map(),p.block.x,p.block.y,p.block.z):1),yaw:(o?.facing||0)*180/Math.PI,step:1});toast('Matériau équipé : '+W.BLOCKS[material].name)}else if(o){assignSlot({kind:'object',type:o.type,variant:o.variant,yaw:(o.facing||0)*180/Math.PI,step:1});toast('Élément équipé : '+o.name)}}
function useCreativeBrush(p,item,remove){if(![p.x,p.y,p.z].every(Number.isFinite)||!W.activeCell(map(),p.x,p.y))return;let box=CT.brushBox(p,item,remove);if(!box)return;const key=[box.x,box.y,box.z,remove].join(',');if(creativeStroke.seen.has(key))return;creativeStroke.seen.add(key);try{let changed=0;if(item.kind==='fogbrush'){for(let y=box.y;y<box.y+box.d;y++)for(let x=box.x;x<box.x+box.w;x++){if(!W.activeCell(map(),x,y))continue;let k=W.cellKey(x,y),i=map().fog.indexOf(k);if(remove&&i>=0){map().fog.splice(i,1);changed++}else if(!remove&&i<0){map().fog.push(k);changed++}}}else{if(item.operation==='terrain'){box.h=1;box.z=Math.floor(p.z)-(remove?1:0)}let plan=CT.planEdit(map(),box,item,remove);changed=CT.applyEdit(map(),plan);if(plan.skipped)$('#hint').textContent=plan.skipped+' positions protégées.'}if(changed){creativeStroke.changed=true;settleBlockActors();invalidate();creativeAimDirty=true;}}catch(error){toast(error.message)}}
function creativeZonePlan(remove=false){if(!creativeZone)throw Error('Définissez les coins A et B avec la baguette.');let box={...creativeZone,z:Math.floor(creativeZone.z),h:Math.max(1,Math.ceil(creativeZone.h))};return CT.planEdit(map(),box,world.builder.zoneTool||CT.defaultToolConfig(),remove)}
function editCreativeZone(apply=false,remove=false){try{const plan=creativeZonePlan(remove);$('#creativeEditReport').textContent=plan.count+' modifications prévues · '+plan.skipped+' éléments / positions protégés.';drawBrush={...plan.box,zone:true};schedule();if(apply&&plan.count){change(()=>{CT.applyEdit(map(),plan);settleBlockActors()});$('#creativeEditReport').textContent='Opération appliquée · Ctrl + Z pour annuler.'}}catch(error){$('#creativeEditReport').textContent=error.message;toast(error.message)}}
