 $('#creativeReach').onchange=e=>{const n=Number(e.target.value);if(Number.isFinite(n)&&n>=3&&n<=32){world.builder.reach=n;queueSave();creativeAimDirty=true}};$('#inventoryLauncher').onclick=()=>toggleInventory(true);$('#enterCreative').onclick=captureCreative;$('#captureInventory').onclick=()=>toggleInventory(true);$('#openHeldSettings').onclick=openCreativeSettings;$('#resumeCreative').onclick=captureCreative;$('#zoneConfigure').onclick=()=>{assignSlot({kind:'selection',name:'Baguette de zone'});openCreativeSettings()};$('#settingsZone').onclick=()=>{if(heldItem()?.kind==='brush'){world.builder.zoneTool=structuredClone(creativeConfig());assignSlot({kind:'selection',name:'Baguette de zone'});queueSave()}creativeCategory='zone';inventoryKey='';renderInventory()};
 for(const [id,key]of [['editSize','size'],['editHeight','height'],['editMaterial','material'],['editShape','shape'],['editMask','mask'],['editSeed','seed']])$('#'+id).onchange=e=>{const conf=creativeConfig();let value=['size','height','seed'].includes(key)?Number(e.target.value):e.target.value;if(typeof value==='number'&&(!Number.isFinite(value)||value<1||value>(key==='seed'?999999:9))){syncCreativeSettings();return}conf[key]=value;queueSave();creativeAimDirty=true;};
